const detail = (title, body) => `<details class="chapter-details"><summary>${title}<span>+</span></summary><div>${body}</div></details>`;
const list = items => `<ul class="plain-list">${items.map(x=>`<li>${x}</li>`).join('')}</ul>`;
const note = (label,text) => `<div class="editorial-note"><strong>${label}</strong><p>${text}</p></div>`;
const demo = (id,label='現有 MathConcept 示範系統') => `<div class="demo-wrap"><div class="demo-caption"><span>${label}</span><span>${id==='rollout'?'建議交付次序':'提案專用獨立示範'}</span></div><div class="demo" data-demo="${id}" id="demo-${id}"></div></div>`;
const proposedFlow = (label,steps,text) => `<div class="proposed-flow"><span class="field-label">${label}</span><ol>${steps.map(step=>`<li>${step}</li>`).join('')}</ol><p>${text}</p></div>`;
export const chapters = [
 {id:'vision',title:'方案概覽'},
 {id:'system',title:'一套互相連繫的系統',kicker:'共用的營運模式',heading:'從總部的課程規劃<br>連繫到學生的下一堂。',intro:'每個角色都能看到所需的工具和資料，圍繞同一批學生、課堂及已審批教材，讓各項工作互相銜接。',body:demo('system')+detail('各個角色如何配合',list(['總部編製及審批課程、管理存取權限，並訂定中心政策。','中心職員處理報名、課堂安排、家長要求及收費事宜。','老師從所教班別選取學生、派發工作紙，並檢視學習情況。','學生在自己的學習資料夾內完成習作；家長則透過獨立應用程式處理課堂及繳費安排。','每份習作均連結至工作紙的指定已發布版本；答案的存取權限則另行核實。']))+note('同一套系統，各司其職','可在此試用現有的行政、老師、家長及學生介面。總部教材發布、課程權限及正式系統整合屬於建議新增的功能。')},
 {id:'protection',title:'保護課程教材',kicker:'受控的教材分發',heading:'妥善保管原檔。<br>讓教學取用更方便。',intro:'以受控教材庫取代直接開放共用雲端硬碟，按教學需要分發教材，並記錄教材如何供閱覽及列印。',body:proposedFlow('建議的存取及列印流程',['非公開原檔','已審批頁面','獲授權閱覽或列印','發放紀錄'],'總部保留教材原檔。已審批頁面的閱覽及列印工作，均受帳戶、中心及習作權限限制。受控列印及副本識別碼仍屬建議功能。')+`<div class="three-columns"><article><h3>按角色授權</h3><p>總部管理原檔；中心取用獲授權的課程教材；學生查看已獲派發的習作。</p></article><article><h3>授權列印</h3><p>已審批的列印工作送往受管理裝置及打印機，並設用量限制及操作紀錄。</p></article><article><h3>副本可追溯</h3><p>每份副本的發放編號，均連結至工作紙版本、中心、帳戶及列印工作。</p></article></div>`+detail('管控措施、限制及驗證',list(['將原始 PDF 及編製檔案存放於非公開儲存空間。如須保護原檔，則只提供獲授權的頁面呈現版本。','受管理的列印連接裝置及打印機仍會處理列印資料，須明確規範儲存、列印暫存清理、管理權限及失敗工作的處理方式。','建議以不顯眼的點陣圖案，配合可讀的發放編號。必須測試從掃描、相片及影印本中還原識別資料的效果，才可作出效能承諾。','只要可閱覽或列印，便仍可能被截圖、拍攝或再次複製。這些措施可減少輕易大量擷取教材的情況，並協助調查，但無法杜絕所有外洩。','還原所得的編號可識別已發放的副本，但不能證明是哪一位人士洩漏。','中心或帳戶停用時，必須撤銷存取權限；已拍攝或列印的內容則無法收回。']))},
 {id:'library',title:'沿用現有教材庫',kicker:'保留、整理、逐步提升',heading:'讓逾 200,000 份檔案繼續發揮作用。<br>保留累積的教學價值。',intro:'先讓現有教材可搜尋、可派發，再逐步將優先教材轉換為可重用及編輯的題目。',body:demo('library','課程目錄及習作派發')+note('現有教材目錄','示範採用已提供的課程索引。小三及小六設有示例題目；工作紙原檔及可編輯內容的轉換仍有待接入。')+`<div class="three-columns numbered"><article><span>01</span><h3>保留原有頁面</h3><p>沿用原本版面，加入搜尋、受控存取及數碼書寫區。</p></article><article><span>02</span><h3>重用現有題目</h3><p>從現有頁面選取題目及附圖，記錄來源後重用。</p></article><article><span>03</span><h3>可編輯內容</h3><p>核對擷取的文字、算式及答案後，發布為可直接編輯的題目。</p></article></div>`+detail('教材遷移範圍及品質檢查',list(['先盤點實際檔案格式、頁數、檔案完整性及資料夾結構，再估算轉換工作量。檔案數目不等於題目數目。','保留唯讀主檔、原始路徑、固定參考編號及版本關係，並將完全相同的重複檔案與修訂版本分開識別。','將已審批的工作紙編號對應至老師的學習進度表，包括年級、課題及教材系列。','供搜尋用的文字識別結果可能有誤；擷取版本完成核對前，仍以忠於原檔的頁面作教學依據。','檢查小數點、分數、單位、附圖、分題及答案對應關係。較難轉換的題目，在核實前先保留為圖片。','分別量度整個教材庫的涵蓋程度，以及已核實、可編輯題目的數量。教材庫遷移與結構化內容轉換屬於不同的交付範圍。']))},
 {id:'authoring',title:'編製新教材',kicker:'以數碼使用為先',heading:'為數學教學而設的<br>工作紙編製工具。',intro:'組合已審批題目、編寫新題目，並預留足夠思考及運算空間。同一套內容可用於直向平板，亦可經妥善分頁後列印。',body:proposedFlow('建議的教材編製流程',['編寫或選取題目','審閱答案及版面','發布版本'],'將已審批題目與新內容組成工作紙，經審閱後發布版本，供老師派發。原生教材編製及 AI 輔助功能尚未納入現有示範。')+`<div class="two-columns"><article><h3>有結構的教材內容</h3><p>每道題目均有獨立的題幹、數學符號、圖片等素材、答案、評分指引、課程標籤及版本，再由工作紙將題目組合起來。</p></article><article><h3>AI 輔助，編審把關</h3><p>AI 可協助搜尋例題、草擬變化題及轉換內容。教材發布前，由編製人員審閱題目、答案及版面。</p></article></div>`+detail('教材編製及 AI 功能範圍',list(['先提供文字格式、算式、圖片、可重用題目、答案欄及手寫空間，再按課程優先次序加入專門的互動圖形。','AI 生成內容一律視為草稿。適合的題型可採用計算核對，題意、難度、附圖及解題步驟則須由人手審閱。','AI 處理須遵從議定的教材使用權限，並使用獲批准的服務供應商或私人處理安排。本建議書並不構成將教材庫上載至外部 AI 服務的授權。','學生端收到的資料、搜尋結果及匯出內容均不得包含答案或教師備註，僅在畫面上隱藏並不足夠。','同時提供平板及 A4 預覽。發布檢查須涵蓋分頁位置、運算空間，以及同一道題目的各部分是否保持在一起。','已派發習作保留原有版本。修改教材庫時會建立新版本，不會改動已發放的習作。']))},
 {id:'teacher',title:'老師教學工作台',kicker:'備課與教學',heading:'讓學習進度表<br>成為日常教學工作台。',intro:'選擇班別及學生，即可直接派發合適的工作紙。先從學生所屬年級開始，老師亦可按需要瀏覽其他級別。',body:demo('teacher')+note('相連的操作示例','選好工作紙後，按「Send to student」（發送給學生），再按「View student app」（查看學生應用程式），即可開啟該學生的學習資料夾。「Prepare for later」（留待之後使用）會將習作鎖定，直至老師開放。')+detail('教學流程',list(['將班別及學生放在精簡側欄，並按老師實際授課時段分組。','在學習進度表集中顯示工作紙系列，讓老師按年級、課題及工作紙編號查找。','清楚區分已派發習作、學生進度、待批改習作及改正。職員可查看相關習作內容。','老師可選擇課堂習作或家課，並派發已審批的工作紙版本。預備日後使用的習作，在老師開放前保持鎖定。','手寫運算、批改及改正紀錄均保留在原有題目及習作版本之下。']))},
 {id:'student',title:'學生學習空間',kicker:'熟悉的資料夾，轉為數碼使用',heading:'更多空間寫出解題過程。<br>更少介面操作上的分心。',intro:'以三個熟悉分類整理習作：現在要做、已完成，以及老師預備日後使用的習作。以直向平板及書寫體驗為設計重點。',body:demo('student')+detail('學生體驗及裝置',list(['目前習作包括上一堂的改正；已完成習作仍可供重溫。','老師開放前，學生無法開啟日後習作。存取限制須在介面以外的系統層面執行。','保持操作按鈕精簡，並可切換至全螢幕書寫。家長及學生介面使用香港繁體中文。','筆跡須以固定的頁面或題目座標儲存，避免版面改動後將學生的運算過程移到錯誤題目。','試行期間須驗證觸控筆操作、防誤觸、儲存及重新連線處理，以及支援裝置。離線使用須另行訂明政策及範圍。','自動批改只適用於已驗證的題型；手寫推理及解題方法的給分仍須支援老師審閱。']))},
 {id:'operations',title:'中心與家長協調',kicker:'讓課堂安排清晰明確',heading:'職員可依據的時間表。<br>家長清楚知道下一步。',intro:'即時記錄請假，再由職員與家長協調補堂。臨時及永久調堂均在確認前顯示對課堂數目的影響。',body:demo('operations')+`<div class="two-columns"><article><h3>家長提出請假</h3><p>應用程式確認請假後，讓家長按需要提供補堂日期偏好，並清楚說明客服會聯絡家長完成補堂安排。</p></article><article><h3>職員確認安排</h3><p>原有課堂會以刪除線標示，並移至請假區。只有職員確認雙方同意的時間後，才會排入補堂。</p></article></div>`+detail('課堂安排規則及溝通',list(['職員可將課堂拖放至新時段或請假區，亦須提供可用鍵盤完成相同操作的方式。','以淺灰色標示老師未能授課的時段。確認更改前，先核對名額、可用時間及時間衝突。','可設定更改生效日期及選填結束日期。臨時更改結束後，恢復原有恆常上課安排。','比較受影響課堂：若課堂增加，須明確決定如何處理額外課堂；若課堂減少，則須決定是否保留補堂額度。','將收據及課堂安排的修訂互相連結，保留審計紀錄及原始紀錄。最終文件的修訂及日期政策仍須議定。','學生資料包括餘下課堂日期。家長溝通及課堂備註須連結至相關學生及課堂。']))},
 {id:'billing',title:'繳費及最終對帳',kicker:'清楚顯示下一步要做甚麼',heading:'掌握待處理事項。<br>以銀行紀錄完成核對。',intro:'逐張帳單追蹤家長付款、中心審核及收據發出進度，再於獨立的最終對帳流程中，將已發出的收據與銀行紀錄核對。',body:demo('billing')+note('發出收據與銀行對帳分開處理','建議的「Auto-sent」（自動發送）政策，會在付款證明通過議定檢查後發出收據，但不代表已與銀行入帳紀錄核對。中心亦可採用人手審核，再透過最終對帳找出差異。')+detail('收費規則及例外情況',list(['每列代表一張帳單。同一名學生可同時有較早期的未繳帳單、待審核帳單，以及已完成的帳單。','預設顯示中心待審核清單。顯示繳費限期及逾期帳單；付款證明由最舊開始排列，收據則由最新開始排列。','可按學生姓名、學生編號或帳單編號搜尋，並按收費類別及所選收費月份篩選。正式系統只載入目前頁面，每頁約 25 列。','在已篩選的清單中並排檢視帳單及付款證明。確認後發出收據；退回付款證明時須填寫原因，並要求補交證明，而非再次付款。','儲存失敗時保留審核畫面。記錄已發出的提醒，避免 24 小時內重複發送。已取消及已作廢帳單另行封存。','建議中心預設採用「Auto-sent」（自動發送）。付款證明未通過檢查或結果不確定時，轉交人手審核。本建議書中的檢查屬模擬功能，正式使用前仍須驗證。','銀行交易只匯入一次，避免同一筆入帳重複分配，並標示遺漏、多出或配對不明確的紀錄。付款發起、證明提交、收據發出及銀行入帳日期須分開記錄。','現金、支票、合併付款、部分付款及退款須各自議定處理方法。直接串接銀行 API 屬可選項目，尚未確認；基本方案為匯入銀行月結單。']))},
 {id:'franchise',title:'跨中心營運',kicker:'以一致管理支援擴展',heading:'總部訂定標準。<br>中心處理日常營運。',intro:'為每間加盟中心提供所需的課程教材及營運工具，清楚劃分權限，並由總部統一管理教材發布及存取政策。',body:demo('franchise','荃灣及坑口')+note('共用應用程式','兩間中心共用同一套應用程式，並各自保留中心識別、老師及示範紀錄。總部權限及跨中心報表屬建議新增功能。')+detail('跨中心管理',list(['分隔各中心的資料及獲授權課程。切換畫面上的中心選項，絕不可繞過伺服器端的權限核實。','總部管理教材發布、版本及課程使用權。中心的教學及營運權限可按議定的角色模式設定。','按議定門檻追蹤異常存取或列印量，交由既定程序審查，不應自動判定違規。','讓中心掌握尚未完成的課堂安排及繳費事項。比較不同中心的表現前，須先議定報表定義。','擴展規劃須包括新中心啟用、職員變動、加盟中心終止合作、支援範圍及語言要求。','總部保留所提供課程教材及營運資料的擁有權。協議須訂明軟件擁有權、授權、匯出及交接安排。']))},
 {id:'rollout',title:'遷移、試行及推展',kicker:'先驗證流程，再逐步擴展',heading:'從一間中心開始。<br>以實際成果支持下一步。',intro:'先以真實教材、裝置及職員日常流程驗證，再擴展至其他中心。每個階段均按成果作出雙方議定的決定。',body:demo('rollout','交付路線圖')+`<div class="two-columns responsibility"><article><h3>MathConcept 提供</h3><p>獲授權教材及原始資料、課程及營運負責人、具代表性的例外情況、試行用戶，以及適時的審閱決定。</p></article><article><h3>交付團隊提供</h3><p>議定的設計及開發、遷移工具、驗證報告、職員培訓、文件及推出支援。</p></article></div>`+detail('試行驗收示例',list(['老師能找到正確的已審批工作紙、派發予學生，並在議定裝置上檢視學生已儲存的習作。','學生遇到議定的中斷情況後，能繼續已儲存的習作，筆跡不會遺失或錯位。','家長提出請假後，原有課堂及職員待辦清單會更新，而不會自動確認補堂時間。','帳單按議定的人手或自動收據政策處理；匯入月結單後，系統會標示無法解釋的差異及重複分配。','未獲授權的中心無法取得原始檔案、其他中心的學生紀錄或受限制答案。','已審批列印工作會留下紀錄，並在成功、失敗及重試時按預期運作。水印還原效果則按議定的拍攝或掃描條件另行量度。','遷移樣本保留所需算式及版面；例外情況須列入報告並解決，或繼續以忠於原檔的頁面形式保留。']))},
 {id:'proposal',title:'範圍、投資及下一步',kicker:'建立清晰的交付基礎',heading:'議定首階段版本。<br>讓下一個決定更具體。',intro:'本初稿提出方案方向，並以可操作的流程供各方討論。待教材庫、營運規則及試行要求完成驗證後，再落實範圍、價格及交付日期。',body:`<div class="scope-matrix"><article><span class="scope-label">基礎功能</span><h3>建議首階段版本</h3><p>按議定試行範圍，提供受控教材庫、老師派發習作、學生學習資料夾、中心及家長流程、帳單待辦清單，以及銀行月結單對帳。</p></article><article><span class="scope-label">分階段開發</span><h3>教材編製及擴展</h3><p>原生工作紙編製、經核實的題目轉換、指定 AI 輔助功能、更完整的報表，以及按計劃推展至更多中心。</p></article><article><span class="scope-label">可行性驗證</span><h3>驗證後再作承諾</h3><p>大量轉換的品質、列印裝置支援、手寫操作、隱蔽水印還原、銀行 API，以及其他付款方式。</p></article></div><div class="commercial-panel"><div><span class="eyebrow">商業安排基礎</span><h3>將投資清楚分為幾個部分。</h3></div><div class="cost-lines"><div><span>平台設計及開發</span><strong>待界定範圍</strong></div><div><span>教材庫遷移及可編輯內容轉換</span><strong>另行報價</strong></div><div><span>寄存、儲存及第三方服務</span><strong>須訂明用量假設</strong></div><div><span>支援、維護及培訓</span><strong>待議定服務條款</strong></div></div></div><div class="decision-box"><span>下一個決定</span><h3>議定具代表性的試行方案及成功指標。</h3><p>確認參與中心、教材樣本、裝置及打印機配置、決策負責人，以及優先處理流程，再將議定範圍轉化為交付計劃及商業建議書。</p><div class="button-row"><button class="primary-button" data-action="reference" data-ref="scope">閱讀詳細範圍 <span>↗</span></button><button class="secondary-button" data-action="reference" data-ref="assumptions">查看待決定事項</button></div></div>`+detail('擁有權、支援及交接',list(['MathConcept 保留其提供的課程教材及營運資料擁有權。新軟件及新內容的擁有權與授權安排須於協議中訂明。','議定寄存責任、獲授權的管理操作、備份及還原安排、資料匯出，以及交接條款。','訂明支援時間、事故處理、更新責任、安全維護及第三方服務依賴。','後續商業建議書的費用及時間表，須以經驗證的範圍為依據。本初稿不構成任何開發價格或交付日期的承諾。']))}
];
export function chapterHTML(c,i){return `<section class="chapter" id="${c.id}" data-chapter="${i}" aria-labelledby="heading-${c.id}"><div class="eyebrow">${String(i+1).padStart(2,'0')} / ${c.kicker}</div><div class="chapter-heading"><h2 id="heading-${c.id}">${c.heading}</h2><p class="section-intro">${c.intro}</p></div>${c.body}</section>`}
export const references = {
 scope:{title:'詳細範圍',body:`<p class="reference-lead">以下為供討論的工作範圍。「建議」項目屬待驗證及議定的交付要求，並不表示正式系統已具備相關功能。</p><h3>課程及教材</h3>${list(['非公開原檔庫、教材目錄、工作紙編號、課程對應、按角色權限搜尋，以及版本紀錄。','先提供忠於原檔的頁面，再逐步加入可重用的圖片題目及經核實的可編輯題目。','教材編製區塊、算式、圖片、運算空間、平板及 A4 預覽，以及審閱和發布權限。','AI 輔助檢索、草擬及轉換，配合獲批准的處理方式，並由人手決定是否發布。'])}<h3>教與學</h3>${list(['按老師時間表整理班別及學生，支援按年級瀏覽，並透過學習進度表派發習作。','課堂習作及家課、目前／已完成／日後習作資料夾、鎖定未開放習作、手寫運算、批改及改正。','固定的習作版本，以及明確的裝置、儲存及重新連線、離線使用驗收準則。'])}<h3>中心及家長事務</h3>${list(['課堂安排、老師可授課時間、課堂備註、餘下課堂及學生資料。','請假確認、選填補堂日期偏好、由職員安排補堂，以及請假區。','單次、臨時及恆常調堂，並檢查時間衝突及課堂數目變化。','家長可見的紀錄及溝通，均連結至相應學生及課堂。'])}<h3>收費</h3>${list(['帳單各階段待辦清單、人手審核、可選的「Auto-sent」（自動發送）政策、提醒、收據紀錄及封存。','正式系統提供搜尋、收費類別及月份篩選，以及由伺服器分頁載入的清單。','銀行月結單匯入、配對建議、款項分配控制、例外情況處理及最終對帳。','現金、支票、退款及合併／部分付款須另行議定規則；銀行 API 屬獨立的可行性評估項目。'])}<h3>總部及加盟中心</h3>${list(['中心資料分隔、課程使用權、角色權限、審批流程及權限撤銷。','存取及列印紀錄、營運監察、遷移報告、培訓及支援安排。'])}<h3>示範範圍及限制</h3><p>內嵌畫面採用現有 MathConcept 示範系統。操作變更儲存於此分頁的提案專用獨立示範工作階段，不會改動主示範系統的已存紀錄，亦不會跨裝置同步。荃灣時間表的姓名及時段來自已提供的時間表；繳費及其他流程紀錄則為示例。小三及小六設有示例題目，其他目錄項目仍須接入工作紙原檔。付款檢查屬模擬功能。總部教材發布、內容轉換、原生教材編製、受控列印及正式系統存取管控，仍屬建議範圍。</p>`},
 technical:{title:'技術方案及安全',body:`<p class="reference-lead">以下為建議架構，須按教材盤點、預計用量及議定的部署環境進一步驗證。</p><h3>三個互相連結的內容層</h3>${list(['原檔：非公開檔案，附有固定識別碼、校驗碼、來源路徑及版本關係。','已發布教材：已審批的頁面呈現版本及結構化題目紀錄，老師用解答另行管理。','習作：指定的已發布版本，以及學生運算過程和批改紀錄。'])}<h3>存取及內容提供</h3><p>驗證用戶身分，並在伺服器端逐項檢查受保護資源的存取權限。學生端收到的資料不得包含答案或受限制原檔。採用受控頁面提供方式、限定權限的列印工作，以及可供審計的操作紀錄。單靠有期限的連結，並不能令可下載原檔變得無法複製。</p><h3>可靠性</h3><p>訂明儲存及重試方式、重複操作防護、月結單重複匯入防護、備份及還原測試。按議定的同時上課班別、頁面請求、筆跡儲存及列印工作量模型，驗證正式系統的負載；只計算學生人數並不構成負載測試。</p><h3>文件轉換</h3><p>以具代表性的數學內容及附圖評估識別工具。保留原檔，並將不確定的轉換結果交由人手審閱。編輯器支援算式，不代表能忠實匯入現有文件。</p><h3>可追溯性</h3><p>每次發放均設獨立編號，對應至非公開紀錄。若每份工作紙須識別十億份副本，且另有資料識別工作紙本身，則副本識別碼至少需要 30 位元；定位、錯誤更正及真偽驗證會再增加所需資料量。不顯眼的列印圖案須獨立驗證，不能保證在遭移除或重新製作後仍可還原。</p><h3>互通及擁有權</h3><p>為總部保留受控的原檔、教材紀錄及營運資料匯出功能。使用便於跨系統傳遞的數學表示格式，並按需要評估兼容 QTI 的資料交換方式。總部匯出權限須與加盟中心的存取權限分開管理。</p><h3>技術參考資料</h3><ul class="source-links"><li><a href="https://docs.mathpix.com/" target="_blank" rel="noopener">Mathpix — STEM 內容識別及文件轉換 ↗</a></li><li><a href="https://tiptap.dev/docs/conversion/content-types/structures-and-media/math-equations" target="_blank" rel="noopener">Tiptap — 算式編輯及匯入限制 ↗</a></li><li><a href="https://www.1edtech.org/standards/qti/index" target="_blank" rel="noopener">1EdTech — 題目及測驗的跨系統互通 ↗</a></li><li><a href="https://docs.aws.amazon.com/AmazonS3/latest/userguide/using-presigned-url.html" target="_blank" rel="noopener">AWS — 簽署下載連結的適用範圍及限制 ↗</a></li><li><a href="https://www.qrcode.com/en/codes/microqr.html" target="_blank" rel="noopener">DENSO WAVE — Micro QR 容量及結構 ↗</a></li></ul><p class="small">以上資料用於可行性研究，並不構成採用個別供應商的承諾，亦不保證準確度、安全性或效能。</p>`},
 assumptions:{title:'待決定事項及責任分工',body:`<p class="reference-lead">以下決定會影響範圍及費用，可於需求確認及試行階段逐項落實。</p><h3>教材</h3>${list(['現有檔案有哪些格式、共有多少頁，以及哪些版本應作為準則？','應優先將哪些年級及工作紙系列轉換為可編輯題目？','由誰核對數學內容、答案，以及教材是否達到發布要求？','可接受哪些外部 AI 或文字識別（OCR）處理安排？'])}<h3>教學及裝置</h3>${list(['須支援哪些平板、觸控筆、瀏覽器、打印機及受管理的列印連接裝置？','是否需要離線做習作？離線時如何處理受保護教材及尚未傳送的習作？','哪些題型需要自動批改、互動圖形或人手審閱？'])}<h3>營運及財務</h3>${list(['確認請假、補堂有效期、調堂及額外課堂規則。','議定收據措辭及「Auto-sent」（自動發送）政策所需的付款證明，並獨立保留銀行對帳狀態。','確認銀行匯出格式、配對規則、現金及支票處理、分拆付款、退款及月結例外情況。','議定通知渠道、訊息保留安排，以及與家長溝通的責任分工。'])}<h3>商業安排及推展</h3>${list(['選定試行中心、參與群組、具代表性的教材樣本及決策負責人。','訂立可量度的驗收準則，並在推展至整間中心或海外前設立審批關口。','議定原始資料整理責任、軟件授權及擁有權、寄存、支援及交接安排。','在上述假設完成驗證後，確認價格、實施時間表及經常性費用。'])}`}
};
